    margin: 0 0 1rem;
    font-size: 1.2rem;
    color: #333;
}

.filter-section {
    margin-bottom: 1.5rem;
}

.filter-section h3 {
    margin: 0 0 0.5rem;
    font-size: 0.95rem;
    color: #555;
}

