    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.25rem 0;
    cursor: pointer;
    font-size: 0.9rem;
}

.filter-empty {
    color: #999;
    font-size: 0.85rem;
    font-style: italic;
}

.price-inputs {
